219→    #[test]
220→    fn live_output_callback_updates_bar() {
221→        let bar = ProgressBar::hidden();
222→        let callback = live_output_callback(bar.clone(), "Running...".to_string(), 4, 2);
223→
224→        callback(OutputLine::Stdout("line 1".to_string()));
225→        let msg = bar.message();
226→        assert!(msg.contains("Running..."));
227→        assert!(msg.contains("line 1"));
228→
229→        callback(OutputLine::Stderr("line 2".to_string()));
230→        let msg = bar.message();
231→        assert!(msg.contains("line 1"));
232→        assert!(msg.contains("line 2"));
233→
234→        // Ring buffer evicts oldest line
235→        callback(OutputLine::Stdout("line 3".to_string()));
236→        let msg = bar.message();
237→        assert!(!msg.contains("line 1"));
238→        assert!(msg.contains("line 2"));
239→        assert!(msg.contains("line 3"));
240→
241→        bar.finish();
242→    }
