  1→//! Visual theme and styling.
  2→
  3→use console::Style;
  4→
  5→/// Bivvy's visual theme.
  6→///
  7→/// See `src/ui/README.md` for color and typography norms.
  8→#[derive(Debug, Clone)]
  9→pub struct BivvyTheme {
 10→    /// Style for success messages (green).
 11→    pub success: Style,
 12→    /// Style for warning messages (orange).
 13→    pub warning: Style,
 14→    /// Style for error messages (red bold).
 15→    pub error: Style,
 16→    /// Style for informational/running elements (fuchsia/magenta).
 17→    pub info: Style,
 18→    /// Style for dim/secondary text.
 19→    pub dim: Style,
 20→    /// Style for highlighted/important text (bold).
 21→    pub highlight: Style,
 22→    /// Style for step titles (bold).
 23→    pub step_title: Style,
 24→    /// Style for headers (fuchsia bold).
 25→    pub header: Style,
 26→    /// Style for step numbers and counters (dim).
 27→    pub step_number: Style,
 28→    /// Style for durations and timestamps (dim).
 29→    pub duration: Style,
 30→    /// Style for commands shown in output (dim italic).
 31→    pub command: Style,
 32→    /// Style for box-drawing borders (dim).
 33→    pub border: Style,
 34→    /// Style for contextual hints (fuchsia dim).
 35→    pub hint: Style,
 36→    /// Style for key labels in key-value displays (bold).
 37→    pub key: Style,
 38→    /// Style for values in key-value displays (normal).
 39→    pub value: Style,
 40→    /// Style for blocked status (orange).
 41→    pub blocked: Style,
 42→}
 43→
 44→impl Default for BivvyTheme {
 45→    fn default() -> Self {
 46→        Self::new()
 47→    }
 48→}
 49→
 50→impl BivvyTheme {
 51→    /// Create the default Bivvy theme.
 52→    pub fn new() -> Self {
 53→        Self {
 54→            success: Style::new().green(),
 55→            warning: Style::new().color256(208),
 56→            error: Style::new().red().bold(),
 57→            info: Style::new().magenta(),
 58→            dim: Style::new().dim(),
 59→            highlight: Style::new().bold(),
 60→            step_title: Style::new().bold(),
 61→            header: Style::new().bold().magenta(),
 62→            step_number: Style::new().dim(),
 63→            duration: Style::new().dim(),
 64→            command: Style::new().dim().italic(),
 65→            border: Style::new().dim(),
 66→            hint: Style::new().magenta().dim(),
 67→            key: Style::new().bold(),
 68→            value: Style::new(),
 69→            blocked: Style::new().color256(208),
 70→        }
 71→    }
 72→
 73→    /// Create a theme without colors (for non-TTY or --no-color).
 74→    pub fn plain() -> Self {
 75→        Self {
 76→            success: Style::new(),
 77→            warning: Style::new(),
 78→            error: Style::new(),
 79→            info: Style::new(),
 80→            dim: Style::new(),
 81→            highlight: Style::new(),
 82→            step_title: Style::new(),
 83→            header: Style::new(),
 84→            step_number: Style::new(),
 85→            duration: Style::new(),
 86→            command: Style::new(),
 87→            border: Style::new(),
 88→            hint: Style::new(),
 89→            key: Style::new(),
 90→            value: Style::new(),
 91→            blocked: Style::new(),
 92→        }
 93→    }
 94→
 95→    /// Format a success message (icon + text in green).
 96→    pub fn format_success(&self, msg: &str) -> String {
 97→        format!("{}", self.success.apply_to(format!("✓ {}", msg)))
 98→    }
 99→
100→    /// Format a warning message (icon + text in orange).
101→    pub fn format_warning(&self, msg: &str) -> String {
102→        format!("{}", self.warning.apply_to(format!("⚠ {}", msg)))
103→    }
104→
105→    /// Format an error message (icon + text in red bold).
106→    pub fn format_error(&self, msg: &str) -> String {
107→        format!("{}", self.error.apply_to(format!("✗ {}", msg)))
108→    }
109→
110→    /// Format a skipped message (icon + text in dim).
111→    pub fn format_skipped(&self, msg: &str) -> String {
112→        format!("{}", self.dim.apply_to(format!("○ {}", msg)))
113→    }
114→
115→    /// Format a step title.
116→    pub fn format_step(&self, name: &str, description: &str) -> String {
117→        format!(
118→            "{} {}",
119→            self.step_title.apply_to(format!("◆ {}", name)),
120→            self.dim.apply_to(description)
121→        )
122→    }
123→
124→    /// Format a header banner.
125→    pub fn format_header(&self, title: &str) -> String {
126→        format!(
127→            "{} {}",
128→            self.header.apply_to("⛺"),
129→            self.highlight.apply_to(title)
130→        )
131→    }
132→}
