135→pub fn should_use_colors() -> bool {
136→    // Check NO_COLOR env var (https://no-color.org/)
137→    if std::env::var("NO_COLOR").is_ok() {
138→        return false;
139→    }
140→
141→    // Check if stdout is a TTY
