  1→//! Unified status vocabulary for consistent CLI output.
  2→//!
  3→//! `StatusKind` provides a single canonical set of status icons and
  4→//! colors used across all commands and display contexts. This replaces
  5→//! the previous split between theme-level symbols and display.rs brackets.
  6→
  7→use super::theme::BivvyTheme;
  8→
  9→/// Canonical status kinds used across all Bivvy output.
 10→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
 11→pub enum StatusKind {
 12→    /// Operation completed successfully.
 13→    Success,
 14→    /// Operation failed.
 15→    Failed,
 16→    /// Operation was skipped.
 17→    Skipped,
 18→    /// Operation has not been run yet.
 19→    Pending,
 20→    /// Operation is currently running.
 21→    Running,
 22→    /// Operation is blocked (dependency failed).
 23→    Blocked,
 24→    /// Non-fatal warning.
 25→    Warning,
 26→}
 27→
 28→impl StatusKind {
 29→    /// Unicode icon for TTY output.
 30→    pub fn icon(self) -> &'static str {
 31→        match self {
 32→            Self::Success => "✓",
 33→            Self::Failed => "✗",
 34→            Self::Skipped => "○",
 35→            Self::Pending => "◌",
 36→            Self::Running => "◆",
 37→            Self::Blocked => "⊘",
 38→            Self::Warning => "⚠",
 39→        }
 40→    }
 41→
 42→    /// Bracketed text for non-TTY output.
 43→    pub fn bracketed(self) -> &'static str {
 44→        match self {
 45→            Self::Success => "[ok]",
 46→            Self::Failed => "[FAIL]",
 47→            Self::Skipped => "[skip]",
 48→            Self::Pending => "[pending]",
 49→            Self::Running => "[run]",
 50→            Self::Blocked => "[blocked]",
 51→            Self::Warning => "[warn]",
 52→        }
 53→    }
 54→
 55→    /// Styled icon string using the given theme.
 56→    pub fn styled(self, theme: &BivvyTheme) -> String {
 57→        let icon = self.icon();
 58→        match self {
 59→            Self::Success => theme.success.apply_to(icon).to_string(),
 60→            Self::Failed => theme.error.apply_to(icon).to_string(),
 61→            Self::Skipped => theme.dim.apply_to(icon).to_string(),
 62→            Self::Pending => theme.dim.apply_to(icon).to_string(),
 63→            Self::Running => theme.info.apply_to(icon).to_string(),
 64→            Self::Blocked => theme.warning.apply_to(icon).to_string(),
 65→            Self::Warning => theme.warning.apply_to(icon).to_string(),
 66→        }
 67→    }
 68→
 69→    /// Format a status line: styled icon + message.
 70→    pub fn format(self, theme: &BivvyTheme, msg: &str) -> String {
 71→        format!("{} {}", self.styled(theme), msg)
 72→    }
 73→
 74→    /// Format a status line for non-TTY: bracketed + message.
 75→    pub fn format_plain(self, msg: &str) -> String {
 76→        format!("{} {}", self.bracketed(), msg)
 77→    }
 78→}
